/* Trivia shown between halls: short facts about the exhibits, their eras and museums themselves. Picked at random, never the same twice in a row. */
(() => {
  'use strict';
  const all = Object.freeze([
    'tyranozaur żył bliżej naszych czasów niż stegozaura? Dzieli je 80 milionów lat, a nas od T-rexa tylko 66.',
    'velociraptor miał pióra i był wielkości indyka? Filmowe raptory to w istocie deinonychy.',
    'Spartanie pod Termopilami nie byli sami? Oprócz 300 Spartan walczyło tam kilka tysięcy innych Greków.',
    'terakotowa armia Qin Shi Huanga liczy około 8 tysięcy żołnierzy i każdy ma inną twarz?',
    'rzymscy legioniści maszerowali po 30 kilometrów dziennie z 30 kilogramami ekwipunku?',
    'Kaligula naprawdę kochał swojego konia Incitatusa, ale historia o mianowaniu go konsulem to prawdopodobnie plotka?',
    'Neron podczas pożaru Rzymu w 64 roku był w Ancjum, 50 kilometrów od miasta?',
    'Attyla zmarł w noc poślubną z krwotoku z nosa, a jego grób do dziś nie został odnaleziony?',
    'imperium Czyngis-chana obejmowało w szczycie 24 miliony kilometrów kwadratowych, więcej niż dzisiejsza Rosja?',
    'wyprawy krzyżowe przyniosły Europie cukier, cytryny i liczby arabskie?',
    'łucznicy z łukami długimi z cisu strzelali 10–12 razy na minutę, a kusznicy ledwie 2?',
    'husaria wygrywała bitwy przy przewadze przeciwnika 5 do 1, a jej skrzydła prawdopodobnie służyły głównie do parady?',
    'Zawisza Czarny dostał przydomek od koloru włosów i karnacji, nie zbroi?',
    'Leonardo da Vinci pisał w lustrzanym odbiciu i był leworęczny?',
    'Kopernik przez ponad 30 lat zwlekał z wydaniem swojego dzieła, a pierwszy egzemplarz zobaczył podobno na łożu śmierci?',
    'muszkiet z XVII wieku trafiał w człowieka z 50 metrów mniej więcej co drugi raz, dlatego strzelano salwami?',
    'Czarnobrody nigdy nie kazał nikomu przejść po desce? To wymysł pisarzy z XIX wieku.',
    'Napoleon nie był niski? Miał około 168 cm, czyli tyle, ile przeciętny Francuz jego czasów.',
    'gilotynę wprowadzono we Francji jako humanitarną metodę egzekucji, równą dla wszystkich stanów?',
    'Kościuszko w testamencie przeznaczył swój amerykański majątek na wykup i edukację niewolników?',
    'Maria Skłodowska-Curie nosiła w kieszeni probówki z radem, a jej notatki do dziś są promieniotwórcze?',
    'pierwszy pistolet maszynowy Thompson był reklamowany jako broń dla farmerów do ochrony ranczo?',
    'Al Capone trafił do więzienia nie za morderstwa, tylko za niepłacenie podatków?',
    'Jurij Gagarin po wylądowaniu w kapsule musiał katapultować się na spadochronie, bo kapsuła lądowała za twardo?',
    'słowo „muzeum” pochodzi od greckiego mouseion, czyli świątyni muz? Pierwsze było w Aleksandrii.',
    'najstarsze muzeum świata, Ennigaldi-Nanna, powstało w Ur około 530 roku p.n.e. i miało opisy eksponatów na glinianych tabliczkach?',
    'Luwr był fortecą, potem pałacem, a muzeum dopiero od rewolucji francuskiej w 1793 roku?',
    'Mona Lisa stała się sławna dopiero po kradzieży z Luwru w 1911 roku? Złodziej trzymał ją dwa lata w walizce.',
    'w muzeach światło jest przyciemnione nie dla nastroju, tylko dlatego, że światło niszczy pigmenty i tkaniny?',
    'nocni strażnicy muzeów naprawdę raportują ruch eksponatów? Zwykle to czujniki reagujące na zmianę temperatury.',
    'Szczerbiec, miecz koronacyjny królów Polski, nigdy nie był wyszczerbiony na bramie Kijowa? Szczerba w nim jest, ale to późniejsza legenda.',
    'katana była składana w kuźni kilkanaście razy, co daje tysiące warstw, ale „składana tysiąc razy” to przesada?',
    'topór był przez większość historii bronią biedniejszych wojowników, bo wymagał mniej stali niż miecz?',
    'Hannibal stracił większość słoni w Alpach, a do bitwy pod Kannami nie dotarł prawdopodobnie ani jeden?',
    'Kleopatra żyła bliżej lądowania na Księżycu niż budowy Wielkiej Piramidy?',
    'Joanna d’Arc nie walczyła mieczem w bitwie? Nosiła sztandar, a sama twierdziła, że nikogo nie zabiła.',
    'Saladyn po zdobyciu Jerozolimy zapłacił z własnej kieszeni okup za część ubogich jeńców, by mogli odejść wolno?',
    'Wilhelm Tell prawdopodobnie nigdy nie istniał? Ta sama historia o strzale w jabłko pojawia się wcześniej w sagach duńskich.',
    'William Wallace nie nosił kiltu i nie malował twarzy na niebiesko? Kilt pojawił się w Szkocji 300 lat później.',
    'Czyngis-chan zakazał tortur i kradzieży bydła, a za zgubienie cudzego konia groziła śmierć?',
    'Mozart napisał swoją pierwszą symfonię w wieku ośmiu lat?',
    'Beethoven, już całkiem głuchy, dyrygował premierą IX symfonii i trzeba było go odwrócić, by zobaczył owacje?',
    'Tesla twierdził, że jego najważniejsze wynalazki powstały w głowie w całości, zanim cokolwiek narysował?',
    'Piłsudski trzymał w gabinecie rozkład jazdy pociągów i uważał, że kolej jest ważniejsza od kawalerii?',
    'rotmistrz Pilecki pisał raporty z Auschwitz na bibułce i przemycał je w praniu?',
  ]);
  let last = -1;
  function pick() { if (!all.length) return ''; let i = Math.floor(Math.random() * all.length); if (all.length > 1 && i === last) i = (i + 1) % all.length; last = i; return all[i]; }
  window.MuseumTrivia = Object.freeze({ all, pick, count: all.length });
})();
